--!strict
-- Grade de alturas do Terrain (Mapa ninja 2026-10-30; Adendo 2: zonas 900×900, Santuário 480×480). GERADO por script em modo Edit a partir de raycasts no
-- Terrain (passo de 6 studs, valores em décimos de stud). Não editar à mão: se o terreno mudar, gerar de novo.
-- `Alturas.em(zonaId, x, z)` = Y do chão (interpolação bilinear, sem alocar); fora da grade usa a borda.
-- `Alturas.y(x, z)` = mesma coisa escolhendo a zona pelo X (zonas a 4000 studs no X).

export type Grade = {
	x0: number,
	z0: number,
	passo: number,
	colunas: number,
	linhas: number,
	dados: { number },
}

local Alturas = {}

-- Dados: 2 caracteres por amostra (base 64, alfabeto abaixo) = décimos de stud + 2048 (cabe -204,8..+204,7).
-- Adendo 2: o CSV antigo passava do limite de 200k caracteres do Source com as zonas 900×900.
local ALFABETO = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local VALOR: { [number]: number } = {}
for i = 1, #ALFABETO do
	VALOR[string.byte(ALFABETO, i)] = i - 1
end

local function decodificar(s: string): { number }
	local n = #s // 2
	local t = table.create(n, 0)
	for i = 1, n do
		local a, b = string.byte(s, 2 * i - 1, 2 * i)
		t[i] = (VALOR[a] * 64 + VALOR[b] - 2048) / 10
	end
	return t
end

local grades: { [string]: Grade } = {}
grades.Vila = { x0 = -450, z0 = -450, passo = 6, colunas = 151, linhas = 151, dados = decodificar("") }
grades.Bambuzal = { x0 = 3550, z0 = -450, passo = 6, colunas = 151, linhas = 151, dados = decodificar("") }
grades.Templo = { x0 = 7550, z0 = -450, passo = 6, colunas = 151, linhas = 151, dados = decodificar("") }
grades.Santuario = { x0 = 11760, z0 = -240, passo = 6, colunas = 81, linhas = 81, dados = decodificar("") }

-- Zonas em ordem de X (centro), pra `Alturas.y`.
local IDS = { "Vila", "Bambuzal", "Templo", "Santuario" }
local CENTROS_X = { 0, 4000, 8000, 12000 }

function Alturas.em(zonaId: string, x: number, z: number): number
	local g = grades[zonaId]
	if not g then
		return 0
	end
	local passo = g.passo
	local fx = math.clamp((x - g.x0) / passo, 0, g.colunas - 1.001)
	local fz = math.clamp((z - g.z0) / passo, 0, g.linhas - 1.001)
	local ix = math.floor(fx)
	local iz = math.floor(fz)
	local tx = fx - ix
	local tz = fz - iz
	local d = g.dados
	local i = iz * g.colunas + ix + 1
	local a = d[i]
	local b = d[i + 1]
	local c = d[i + g.colunas]
	local e = d[i + g.colunas + 1]
	return (a + (b - a) * tx) + ((c + (e - c) * tx) - (a + (b - a) * tx)) * tz
end

-- Id da zona cujo centro (X) está mais perto.
function Alturas.zonaEm(x: number): string
	local melhor = 1
	local menor = math.huge
	for i = 1, #CENTROS_X do
		local dist = math.abs(x - CENTROS_X[i])
		if dist < menor then
			menor = dist
			melhor = i
		end
	end
	return IDS[melhor]
end

function Alturas.y(x: number, z: number): number
	return Alturas.em(Alturas.zonaEm(x), x, z)
end

return Alturas
